local classes = {}

classes.AdminClusterUnreachable = errors.define({
  tag = "AdminClusterUnreachable",
  categories = { "BadRequestError" },
  matchers = {
    { status = 400, message = { includes = "failed connecting to the cluster's control plane" } },
    { status = 400, message = { includes = "could not fetch bare metal cluster version" } },
  },
  fields = { "details" },
})
classes.BadRequest = errors.define({
  tag = "BadRequest",
  categories = { "BadRequestError" },
  matchers = { { status = 400 } },
  fields = { "details" },
})
classes.Conflict = errors.define({
  tag = "Conflict",
  categories = { "ConflictError" },
  matchers = { { status = 409 } },
  fields = { "details" },
})
classes.Forbidden = errors.define({
  tag = "Forbidden",
  categories = { "AuthError" },
  matchers = { { status = 403 } },
  fields = { "details" },
})
classes.NotFound = errors.define({
  tag = "NotFound",
  categories = { "BadRequestError" },
  matchers = { { status = 404 } },
  fields = { "details" },
})

